#include "Diagnosis.h"
namespace injector_diagnostic {std::vector<DiagnosisStep> Diagnosis::createWorkflow(const DtcInfo& d)const{return {{"Fault Code",d.code+" - "+d.description,"Review possible causes"},{"Possible Causes",d.possibleCauses.empty()?"No database causes available.":d.possibleCauses.front(),"Perform sensor check"},{"Sensor Check","Simulation workflow: sensor inspection required.","Perform wiring check"},{"Wiring Check","Simulation workflow: wiring/connector inspection required.","Review test result"},{"Test Result","No physical test performed in Simulation Mode.","Perform next recommended check on real vehicle"}};}}
